query DocumentsLibrary($show: String, $q: String, $queue: String, $deleted: Boolean) {
    documentsLibrary(show: $show, q: $q, queue: $queue, deleted: $deleted) {
      viewer { hr name personId askAfterUpload } show q queue deleted
      sections { id kind name count }
      needsYou { id kind title detail dueOn documentId typeKey }
      tiles { key label count detail }
      queueRows { id title kind person { personId name teamName } detail dueOn tone documentId requestId typeKey action }
      rows { id title kind typeKey typeName level confidential everyone who { label people { personId name teamName } } subject { personId name teamName } pages mediaType updatedAt expiresOn status { label tone } mine aboutMe deletedAt sectionIds } total types { key name kind filedTo confidential } people { personId name teamName }
    }
  }
